DisplayData.DrawData.Add(FQuestItemComponentDebugDrawData(EQuestItemComponentDebugStyleType::NewLineText, TEXT("Esta é uma mensagem de exemplo: ")));
DisplayData.DrawData.Add(FQuestItemComponentDebugDrawData(EQuestItemComponentDebugStyleType::PopStyleColor));

DisplayData.DrawData.Add(FQuestItemComponentDebugDrawData(EQuestItemComponentDebugStyleType::PushStyleColor, QuestItemComponentDebugStrings::Color_Green));
DisplayData.DrawData.Add(FQuestItemComponentDebugDrawData(EQuestItemComponentDebugStyleType::SameLineText, TEXT("Olá, mundo!")));
DisplayData.DrawData.Add(FQuestItemComponentDebugDrawData(EQuestItemComponentDebugStyleType::PopStyleColor));

